-- =============================================================================
-- RAG leve de legislação — Corpus Curado (Batch 9)
-- Cobertura das matérias jurídicas restantes:
-- - Direito Penal Militar (24): Aplicação (155), Teoria Geral (157), Penas (281),
--   Dever Militar (297), Disciplina (328) e Adm. Militar (293)
-- - Direito Processual Penal Militar (25): IPM (158), Ação Penal (282), Competência (283),
--   Flagrante (159) e Processos Especiais (294)
-- - Direito Ambiental (38): PNMA (444), SNUC (270), Competências LC 140 (555),
--   Manejo do Fogo Lei 14.944/2024 (443) e Sanções (275)
-- - Direito Empresarial (34): Teoria da Empresa (571), Societário (570), Falência e RJ (254),
--   S.A. (532) e Estatuto ME/EPP (572)
-- - Direito Financeiro (36): Dívida Ativa e ARO (263), Despesa (264), Orçamento (265)
-- - Legislação Bancária e SFN (73): SFN, BACEN e Autonomia LC 179/2021 (567)
--
-- Fontes Oficiais: Presidência da República (Planalto) e Constituição Federal.
-- Dispositivos vigentes e atualizados (Leis 14.688/2023, 14.944/2024, 14.112/2020, LC 179/2021).
-- Sem dispositivos revogados. Idempotente.
-- =============================================================================

insert into public.legislacao_artigos (referencia, texto, vigencia_de, id_materia, id_topico) values

-- -----------------------------------------------------------------------------
-- DIREITO PENAL MILITAR (ID 24)
-- -----------------------------------------------------------------------------
('CPM — art. 1º e 2º', 'Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal. Ninguém pode ser punido por fato que lei posterior deixa de considerar crime, cessando em virtude dela a execução e os efeitos penais da condenação. A lei posterior, que de qualquer outro modo favorece o agente, aplica-se retroativamente, ainda quando já tenha sobrevindo sentença condenatória transitada em julgado.', '1969-10-21', 24, 155),
('CPM — art. 9º (Crime Militar em Tempo de Paz)', 'Consideram-se crimes militares, em tempo de paz: I - os crimes de que trata este Código, quando definidos de modo diverso na lei penal comum, ou nela não previstos; II - os crimes previstos neste Código e os previstos na legislação penal comum, quando praticados: a) por militar da ativa contra militar na mesma situação; b) por militar da ativa em lugar sujeito à administração militar contra militar da reserva, reformado ou civil; c) por militar em serviço ou atuando em razão da função; d) por militar em comissão ou formatura militar; e) por militar da ativa contra o patrimônio sob administração militar ou a ordem administrativa militar. § 2º Os crimes dolosos contra a vida praticados por militares das Forças Armadas contra civil serão da competência da Justiça Militar da União quando praticados no contexto de cumprimento de atribuições de GLO, do Presidente da República ou segurança de instituição militar. (Redação da Lei nº 14.688/2023)', '2023-09-20', 24, 157),
('CPM — art. 55 e 59 (Penas Militares)', 'As penas principais são: a) morte; b) reclusão; c) detenção; d) prisão; e) impedimento; f) suspensão do exercício do posto, graduação, cargo ou função; g) reforma. A pena de morte é executada por fuzilamento e somente é aplicável em tempo de guerra.', '1969-10-21', 24, 281),
('CPM — art. 149 e 160 (Crimes contra a Autoridade Militar)', 'Motim: reunirem-se militares agindo contra a ordem de superior ou recusando obediência; se os agentes estavam armados, o crime é de revolta. Pena: reclusão, de 3 a 8 anos para o motim, e de 8 a 20 anos para a revolta, com aumento para os cabeças. Desrespeitar superior diante de outro militar: Pena - detenção, de 3 meses a 1 ano.', '1969-10-21', 24, 328),
('CPM — art. 187 e 195 (Dever Militar: Deserção e Abandono de Posto)', 'Deserção: ausentar-se o militar, sem licença, da unidade em que serve, ou do lugar em que deve permanecer, por mais de 8 (oito) dias: Pena - detenção, de 6 meses a 2 anos. Abandono de posto: abandonar, sem ordem superior, o posto ou lugar de serviço que lhe tenha sido designado, ou o serviço que lhe cumpria, antes de terminá-lo: Pena - detenção, de 3 meses a 1 ano.', '1969-10-21', 24, 297),
('CPM — art. 303 e 308 (Crimes contra a Administração Militar)', 'Peculato militar: apropriar-se de dinheiro, valor ou qualquer outro bem móvel, público ou particular, de que tem a posse ou detenção em razão do cargo ou comissão, ou desviá-lo em proveito próprio ou alheio: Pena - reclusão, de 3 a 15 anos. Corrupção passiva: receber ou aceitar promessa de vantagem indevida para praticar, omitir ou retardar ato de ofício: Pena - reclusão, de 2 a 8 anos.', '1969-10-21', 24, 293),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL PENAL MILITAR (ID 25)
-- -----------------------------------------------------------------------------
('CPPM — art. 9º e 10 (Inquérito Policial Militar)', 'O Inquérito Policial Militar é o procedimento administrativo sumário que tem por fim apurar a autoria e a materialidade dos crimes militares e sua autoria, ministrando elementos para a propositura da ação penal. O inquérito deverá terminar no prazo de 20 (vinte) dias se o indiciado estiver preso, contados a partir da efetivação da prisão; ou no prazo de 40 (quarenta) dias quando estiver solto, admitida a prorrogação deste por mais 20 dias mediante despacho fundamentado.', '1969-10-21', 25, 158),
('CPPM — art. 29 e 33 (Ação Penal Militar)', 'A ação penal militar é pública e somente pode ser promovida por denúncia do Ministério Público Militar. A denúncia deve conter a exposição do fato criminoso com todas as suas circunstâncias, a qualificação do acusado, a classificação do crime e o rol das testemunhas.', '1969-10-21', 25, 282),
('CPPM — art. 82 e CF art. 125, § 4º (Competência da Justiça Militar)', 'O foro militar é especial e compreende a Justiça Militar da União e a Justiça Militar dos Estados. Compete à Justiça Militar Estadual processar e julgar os militares dos Estados nos crimes militares definidos em lei e as ações judiciais contra atos disciplinares militares, cabendo ao tribunal competente decidir sobre a perda do posto e da patente dos oficiais e da graduação das praças. Compete aos juízes de direito do juízo militar processar e julgar, singularmente, os crimes militares cometidos contra civis.', '1988-10-05', 25, 283),
('CPPM — art. 243 e 244 (Prisão em Flagrante Militar)', 'Qualquer pessoa poderá e os militares deverão prender quem for encontrado em flagrante delito militar. Considera-se em flagrante delito quem: está cometendo o crime; acaba de cometê-lo; é perseguido em situação que faça presumir ser ele o autor; é encontrado com instrumentos, armas ou objetos que façam presumir sua autoria.', '1969-10-21', 25, 159),
('CPPM — art. 451 e 458 (Processos Especiais de Deserção e Insubmissão)', 'No crime de deserção, consumado o prazo de graça de 8 dias, lavrar-se-á termo de deserção instruído com os assentamentos do desertor. A apresentação voluntária ou captura do desertor é condição de procedibilidade para a instrução criminal. O insubmisso que se apresentar ou for capturado será submetido à inspeção de saúde e, se julgado apto para o serviço, será incorporado para início do processo criminal.', '1969-10-21', 25, 294),

-- -----------------------------------------------------------------------------
-- DIREITO AMBIENTAL (ID 38)
-- -----------------------------------------------------------------------------
('Lei nº 6.938/1981 — art. 2º, 3º e 14 (PNMA)', 'A Política Nacional do Meio Ambiente tem por objetivo a preservação, melhoria e recuperação da qualidade ambiental. Considera-se poluição a degradação da qualidade ambiental resultante de atividades que direta ou indiretamente: prejudiquem a saúde e segurança; criem condições adversas às atividades sociais; afetem desfavoravelmente a biota. O poluidor é obrigado, independentemente da existência de culpa (responsabilidade civil objetiva - teoria do risco integral), a indenizar ou reparar os danos causados ao meio ambiente e a terceiros.', '1981-08-31', 38, 444),
('Lei nº 9.985/2000 — art. 2º, 7º e 8º (SNUC)', 'O Sistema Nacional de Unidades de Conservação da Natureza (SNUC) é constituído pelo conjunto das unidades de conservação (UC) federais, estaduais e municipais, divididas em dois grupos: I - Unidades de Proteção Integral: Estação Ecológica, Reserva Biológica, Parque Nacional, Monumento Natural e Refúgio de Vida Silvestre (admitem apenas o uso indireto dos recursos naturais); II - Unidades de Uso Sustentável: APA, ARIE, Floresta Nacional, Reserva Extrativista, Reserva de Fauna, Reserva de Desenvolvimento Sustentável e RPPN (compatibilizam a conservação com o uso sustentável).', '2000-07-18', 38, 270),
('LC nº 140/2011 — art. 7º, 8º e 9º (Competência Ambiental)', 'Compete à União promover o licenciamento ambiental de empreendimentos: localizados ou desenvolvidos conjuntamente no Brasil e em país limítrofe, no mar territorial, na plataforma continental, na zona econômica exclusiva, em terras indígenas ou que envolvam material radioativo. Compete aos Municípios o licenciamento das atividades de impacto ambiental local; e aos Estados as atividades não privativas da União nem do Município.', '2011-12-08', 38, 555),
('Lei nº 14.944/2024 — art. 1º e 3º (Manejo Integrado do Fogo)', 'É instituída a Política Nacional de Manejo Integrado do Fogo com o objetivo de disciplinar e promover a articulação interinstitucional relativa ao manejo integrado do fogo, à redução da incidência de incêndios florestais e ao reconhecimento do papel ecológico e adaptativo do fogo nos ecossistemas. São princípios: responsabilidade comum dos entes federativos, função social da propriedade, sustentabilidade e substituição do fogo por práticas sustentáveis em ambientes sensíveis.', '2024-07-31', 38, 443),
('Lei nº 9.605/1998 — art. 70 e 72 (Infrações Administrativas Ambientais)', 'Considera-se infração administrativa ambiental toda ação ou omissão que viole as regras jurídicas de uso, gozo, promoção, proteção e recuperação do meio ambiente. As infrações administrativas são punidas com: advertência; multa simples; multa diária; apreensão dos animais, produtos e subprodutos da fauna e flora; destruição ou inutilização do produto; suspensão de venda e fabricação; embargo de obra ou atividade; e demolição.', '1998-02-12', 38, 275),

-- -----------------------------------------------------------------------------
-- DIREITO EMPRESARIAL (ID 34)
-- -----------------------------------------------------------------------------
('Código Civil — art. 966 e 967 (Teoria da Empresa)', 'Considera-se empresário quem exerce profissionalmente atividade econômica organizada para a produção ou a circulação de bens ou de serviços. Parágrafo único. Não se considera empresário quem exerce profissão intelectual, de natureza científica, literária ou artística, ainda com o concurso de auxiliares ou colaboradores, salvo se o exercício da profissão constituir elemento de empresa. É obrigatória a inscrição do empresário no Registro Público de Empresas Mercantis da respectiva sede, antes do início de sua atividade.', '2002-01-10', 34, 571),
('Código Civil — art. 981 e 1.052 (Sociedades e SLU)', 'Celebram contrato de sociedade as pessoas que reciprocamente se obrigam a contribuir, com bens ou serviços, para o exercício de atividade econômica e a partilha, entre si, dos resultados. Na sociedade limitada, a responsabilidade de cada sócio é restrita ao valor de suas quotas, mas todos respondem solidariamente pela integralização do capital social. A sociedade limitada pode ser constituída por 1 (uma) ou mais pessoas, hipótese em que se aplicarão ao documento de constituição do sócio único as disposições sobre o contrato social (Sociedade Limitada Unipessoal - SLU). (Redação dada pela Lei nº 13.874/2019)', '2002-01-10', 34, 570),
('Lei nº 11.101/2005 — art. 47, 48 e 83 (Falência e Recuperação Judicial)', 'A recuperação judicial tem por objetivo viabilizar a superação da situação de crise econômico-financeira do devedor, a fim de permitir a manutenção da fonte produtora, do emprego dos trabalhadores e do interesse dos credores. Pode requerer recuperação judicial o devedor que exercer regularmente suas atividades há mais de 2 anos. Na falência, a classificação dos créditos obedece à seguinte ordem: I - créditos trabalhistas, limitados a 150 salários-mínimos por credor, e por acidente de trabalho; II - créditos com garantia real até o limite do bem gravado; III - créditos tributários; IV - créditos quirografários. (Redação da Lei nº 14.112/2020)', '2005-02-09', 34, 254),
('Lei nº 6.404/1976 — art. 1º, 2º e 4º (Sociedade Anônima)', 'A companhia ou sociedade anônima terá o capital dividido em ações, e a responsabilidade dos sócios ou acionistas será limitada ao preço de emissão das ações subscritas ou adquiridas. A companhia é aberta ou fechada conforme os valores mobiliários de sua emissão estejam ou não admitidos à negociação no mercado de valores mobiliários.', '1976-12-15', 34, 532),
('LC nº 123/2006 — art. 3º (Estatuto da ME e EPP)', 'Para os efeitos desta Lei Complementar, consideram-se microempresas ou empresas de pequeno porte a sociedade empresária, a sociedade simples, a empresa individual de responsabilidade limitada e o empresário individual devidamente registrados que aufiram, em cada ano-calendário: I - microempresa: receita bruta igual ou inferior a R$ 360.000,00; II - empresa de pequeno porte: receita bruta superior a R$ 360.000,00 e igual ou inferior a R$ 4.800.000,00.', '2006-12-14', 34, 572),

-- -----------------------------------------------------------------------------
-- DIREITO FINANCEIRO (ID 36)
-- -----------------------------------------------------------------------------
('Lei nº 4.320/1964 — art. 39 e LC nº 101/2000 art. 38 (Dívida e ARO)', 'Os créditos da Fazenda Pública, de natureza tributária ou não tributária, serão escriturados como receita do exercício em que forem arrecadados, nas respectivas rubricas orçamentárias. Dívida Ativa Tributária é o crédito da Fazenda proveniente de obrigação legal relativa a tributos e multas; Dívida Não Tributária compreende os demais créditos. A operação de crédito por antecipação de receita orçamentária (ARO) destina-se a atender a insuficiência de caixa durante o exercício financeiro e deve ser liquidada, com juros e encargos, até o dia 10 de dezembro de cada ano.', '1964-03-17', 36, 263),
('Lei nº 4.320/1964 — art. 58, 63 e 64 (Estágios da Despesa Financeira)', 'O empenho de despesa é o ato emanado de autoridade competente que cria para o Estado obrigação de pagamento pendente ou não de implemento de condição. A liquidação da despesa consiste na verificação do direito adquirido pelo credor tendo por base os títulos e documentos comprobatórios do crédito. A ordem de pagamento é o despacho que determina que a despesa liquidada seja paga.', '1964-03-17', 36, 264),
('CF/88 — art. 165 e 167 (Normas Orçamentárias Financeiras)', 'Leis de iniciativa do Executivo estabelecerão: I - o plano plurianual; II - as diretrizes orçamentárias; III - os orçamentos anuais (fiscal, de investimento e da seguridade social). É vedada a realização de operações de créditos que excedam o montante das despesas de capital (regra de ouro) e a vinculação de receita de impostos a órgão, fundo ou despesa, ressalvadas as repartições constitucionais e as destinações à saúde e à educação.', '1988-10-05', 36, 265),

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO BANCÁRIA E DO SISTEMA FINANCEIRO NACIONAL (ID 73)
-- -----------------------------------------------------------------------------
('Lei nº 4.595/1964 e LC nº 179/2021 (SFN e Autonomia do Banco Central)', 'O Sistema Financeiro Nacional, estruturado e regulado pela presente Lei, será constituído pelo Conselho Monetário Nacional (CMN), pelo Banco Central do Brasil (BACEN) e pelas instituições financeiras públicas e privadas. O Banco Central do Brasil é autarquia de natureza especial, caracterizada pela ausência de vinculação a Ministério, tutela ou subordinação hierárquica, pela autonomia técnica, operacional, administrativa e financeira. O Presidente e os Diretores do Banco Central terão mandatos de 4 (quatro) anos, não coincidentes com o mandato do Presidente da República. (Redação da Lei Complementar nº 179/2021)', '1964-12-31', 73, 567)

on conflict (referencia) do update set 
    texto = excluded.texto, 
    vigencia_de = excluded.vigencia_de, 
    id_materia = excluded.id_materia, 
    id_topico = excluded.id_topico;
